using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker(reorderThreshold: 5);

    // ── Constructor ──────────────────────────────────────────────

    [TestMethod]
    public void Constructor_DefaultThreshold_DoesNotThrow()
    {
        var tracker = new InventoryTracker();
        Assert.AreEqual(0, tracker.GetStockLevel("ANY-SKU"));
    }

    [TestMethod]
    public void Constructor_NegativeThreshold_Throws()
        => Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => new InventoryTracker(reorderThreshold: -1));

    // ── GetStockLevel ────────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
        => Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));

    // ── AddStock ─────────────────────────────────────────────────

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-1", 20);
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_Accumulates()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.AddStock("SKU-1", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddStock_NonPositiveQuantity_Throws(int qty)
        => Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-1", qty));

    [TestMethod]
    public void AddStock_NullSku_Throws()
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(null!, 1));

    // ── RemoveStock ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveStock_ValidQuantity_ReducesLevel()
    {
        _tracker.AddStock("SKU-1", 20);
        _tracker.RemoveStock("SKU-1", 8);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_EntireStock_LeavesZero()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.RemoveStock("SKU-1", 10);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_MoreThanAvailable_Throws()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 5));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void RemoveStock_NonPositiveQuantity_Throws(int qty)
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-1", qty));
    }

    // ── NeedsReorder ─────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-1", 5); // threshold is 5
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-1", 6);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
        => Assert.IsTrue(_tracker.NeedsReorder("GHOST"));

    [TestMethod]
    public void NeedsReorder_NullSku_Throws()
        => Assert.ThrowsException<ArgumentException>(
            () => _tracker.NeedsReorder(null!));

    // ── TransferTo (warehouse transfers) ─────────────────────────

    [TestMethod]
    public void TransferTo_ValidTransfer_MovesStock()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 20);

        _tracker.TransferTo(destination, "SKU-1", 8);

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-1"));
        Assert.AreEqual(8, destination.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferTo_EntireStock_SourceBecomesZero()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 10);

        _tracker.TransferTo(destination, "SKU-1", 10);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
        Assert.AreEqual(10, destination.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferTo_DestinationAlreadyHasStock_Accumulates()
    {
        var destination = new InventoryTracker();
        destination.AddStock("SKU-1", 5);
        _tracker.AddStock("SKU-1", 10);

        _tracker.TransferTo(destination, "SKU-1", 3);

        Assert.AreEqual(8, destination.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferTo_InsufficientStock_Throws()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 5);

        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferTo(destination, "SKU-1", 10));
    }

    [TestMethod]
    public void TransferTo_SameWarehouse_Throws()
        => Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferTo(_tracker, "SKU-1", 1));

    [TestMethod]
    public void TransferTo_NullDestination_Throws()
        => Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferTo(null!, "SKU-1", 1));

    [TestMethod]
    public void TransferTo_TriggersReorder_AfterTransfer()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 10);

        _tracker.TransferTo(destination, "SKU-1", 6);

        Assert.AreEqual(4, _tracker.GetStockLevel("SKU-1"));
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }
}

